INSERT INTO `posts` (`id`, `slug`, `title`, `excerpt`, `body`, `cover`, `category`, `status`, `wp_id`, `published_at`) VALUES (2,'programs-one-page','Traditional wedding, nikkah & white wedding: one page for every program','Many couples hold two or three ceremonies. Here is how to put them all on one wedding page, with the right dress code, venue and RSVP for each.','<p>A lot of African weddings are really two or three celebrations. The introduction, the traditional wedding, the nikkah or church service, the reception and the after-party can fall on different days, in different towns, with different guest lists.</p><h2>Add each program</h2><p>Pick the type, then add the date, time, venue, dress code and colours. The page counts down to whichever program is next.</p><h2>Keep some programs private</h2><p>Mark a program as private and the page shows it as by invitation only: the venue stays hidden and it is left out of the public RSVP form.</p>','photos/couple-field.jpg','Planning','live',NULL,'2026-10-02 09:00:00');
INSERT INTO `posts` (`id`, `slug`, `title`, `excerpt`, `body`, `cover`, `category`, `status`, `wp_id`, `published_at`) VALUES (3,'cash-gift-registry','Cash & gift registry: how guests can send gifts from anywhere','Family abroad, friends who cannot travel and guests who hate carrying cash can all give from your wedding page. Here is how it works.','<p>Most guests want to give something, but not everyone can be in the hall with cash in hand. A cash and gift registry on your wedding page lets them give from anywhere, in a few taps.</p><h2>Spraying from the phone</h2><p>On Premium pages, guests spray from their phone on the day. Table QR cards open your page, and every spray shows live.</p><h2>Getting the money</h2><p>Gifts and sprays add up in Money. Ask for a payout to your bank or mobile money account whenever you like.</p>','photos/listing-fabric-close.jpg','Guides','live',NULL,'2026-10-14 09:00:00');
INSERT INTO `posts` (`id`, `slug`, `title`, `excerpt`, `body`, `cover`, `category`, `status`, `wp_id`, `published_at`) VALUES (4,'rsvps-entry-passes','RSVPs, entry passes & table cards: keeping your guest list under control','Know who is coming, stop gate-crashers and get guests to their tables without a crowd at the door.','<p>A guest list that grows by itself is one of the biggest wedding headaches. Your page helps you keep it in check, from the first RSVP to the last guest at the door.</p><h2>Entry passes</h2><p>Each confirmed guest gets a pass with a QR code. Your ushers scan it at the gate, so only invited guests get in and nobody is let in twice.</p>','photos/venue-host.jpg','Guides','live',NULL,'2026-10-28 09:00:00');
INSERT INTO `posts` (`id`, `slug`, `title`, `excerpt`, `body`, `cover`, `category`, `status`, `wp_id`, `published_at`) VALUES (5,'apartments-and-rides','Booking apartments & rides for wedding guests without the stress','Guests flying in need somewhere to stay and a way to get around. Here is how to sort it out with sellers on the marketplace.','<p>When family and friends fly in, the questions start: where do we stay, who picks us up, how do we get to the venue? The marketplace gives you one place to find all of it.</p><h2>Chat, then pay</h2><p>Open a listing and chat with the seller about your dates. Your money is held until you confirm.</p>','photos/listing-apartment.jpg','Guests','live',NULL,'2026-11-08 09:00:00');
